import numpy as np

def residual_factors(R):
    R = np.array(R, dtype=float)
    n, k = R.shape
    X = R - R.mean(axis=0)
    if np.linalg.matrix_rank(X) < k:
        raise ValueError("the demeaned factors are dependent")
    Q = np.zeros((n, k))
    for j in range(k):
        f = X[:, j].copy()
        for i in range(j):
            f -= (X[:, j] @ Q[:, i] / n) * Q[:, i]
        Q[:, j] = f / np.sqrt(f @ f / n)
    return (np.round(Q, 6) + 0.0).tolist()
